		await fs.promises.mkdir(folder, { recursive: true });
		const names = [
			`${uid}-profile${type}.png`,
			`${uid}-profile${type}.jpeg`,
			`${uid}-profile${type}-123.jpg`,
			`${uid}-profile${type}-456.bmp`,
		];
		const paths = names.map(name => path.join(folder, name));
		await Promise.all(paths.map(imagePath => fs.promises.writeFile(imagePath, 'image')));
		return paths;
	}

